.cart {
  width: min(30rem, 100%);
  margin: 0 auto;
  text-align: left;
}

.cart__title {
  font-size: 1.125rem;
  margin: 0 0 0.75rem;
}

.cart__list {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid rgba(128, 128, 128, 0.35);
}

.cart__row {
  display: grid;
  grid-template-columns: 1fr auto auto auto;
  align-items: center;
  column-gap: 0.75rem;
  padding: 0.625rem 0;
  border-bottom: 1px solid rgba(128, 128, 128, 0.35);
}

.cart__name {
  min-width: 0;
  overflow-wrap: anywhere;
}

.cart__unit-price {
  font-size: 0.8125rem;
  opacity: 0.7;
  font-variant-numeric: tabular-nums;
}

.cart__subtotal {
  min-width: 5.5rem;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.stepper {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
}

